 db()->beginTransaction();b2bLockLead($u,(int)$o['lead_id']);run('SELECT id FROM wm_b2b_orders WHERE org_id=? AND id=? FOR UPDATE',[$u['org_id'],$oid]);$old=run('SELECT * FROM wm_sample_order_facts WHERE org_id=? AND order_id=? FOR UPDATE',[$u['org_id'],$oid])->fetch();if(($old?(int)$old['version']:0)!==num($b['version']??0)){db()->rollBack();out(['error'=>'Données de commande modifiées'],409);}$link=run("SELECT c.sample_id,s.received_date FROM wm_sample_conversions c JOIN wm_samples s ON s.id=c.sample_id AND s.org_id=c.org_id WHERE c.org_id=? AND c.order_id=? AND c.status='confirmed'",[$u['org_id'],$oid])->fetch();if($link&&$date<$link['received_date']){db()->rollBack();out(['error'=>'La date ne peut pas précéder l’échantillon déjà attribué'],409);}if($old)run('UPDATE wm_sample_order_facts SET order_date=?,currency=?,revenue_ht=?,variable_cost_ht=?,items_json=?,source_note=?,version=version+1 WHERE org_id=? AND order_id=?',[$date,$currency,$revenue,$cost,json_encode($items,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$note,$u['org_id'],$oid]);else run('INSERT INTO wm_sample_order_facts(org_id,order_id,order_date,currency,revenue_ht,variable_cost_ht,items_json,source_note) VALUES(?,?,?,?,?,?,?,?)',[$u['org_id'],$oid,$date,$currency,$revenue,$cost,json_encode($items,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$note]);if($link)sampleEvent($u,(int)$link['sample_id'],'order.facts.updated',$note,['order_id'=>$oid,'before'=>$old?:null,'after'=>['date'=>$date,'currency'=>$currency,'revenue_ht'=>$revenue,'variable_cost_ht'=>$cost,'items'=>$items]]);audit($u,'samples.order.facts.saved',$oid);db()->commit();out(['ok'=>true]);
}
