 $q=text($_GET['q']??'',200);db()->beginTransaction();$rows=run('SELECT s.*,l.name AS client_name,l.status AS client_status,u.email AS owner_email FROM wm_samples s JOIN wm_leads l ON l.id=s.lead_id AND l.org_id=s.org_id LEFT JOIN wm_users u ON u.id=s.owner_id WHERE s.org_id=? AND LOCATE(?,CONCAT(s.reference,\' \',s.title,\' \',l.name))>0 ORDER BY s.id DESC LIMIT 200',[$u['org_id'],$q])->fetchAll();$conversions=run('SELECT c.*,o.reference AS order_reference,o.status AS order_status,s.reference AS sample_reference FROM wm_sample_conversions c JOIN wm_b2b_orders o ON o.id=c.order_id AND o.org_id=c.org_id JOIN wm_samples s ON s.id=c.sample_id AND s.org_id=c.org_id WHERE c.org_id=? ORDER BY c.id DESC LIMIT 200',[$u['org_id']])->fetchAll();$metrics=sampleMetrics($u);$candidates=sampleCandidates($u);$roles=sampleRoles($u);$canCosts=in_array('logistics',$roles,true)||in_array('finance',pilotScopes($u),true);db()->commit();out(['items'=>$rows,'metrics'=>$metrics,'candidates'=>$candidates,'conversions'=>$conversions,'roles'=>$roles,'can_costs'=>$canCosts,'labels'=>SAMPLE_LABELS,'business_day'=>businessDay(),'limits'=>'Liste : 200 demandes ; rapprochements : 200 demandes reçues et 200 commandes récentes, fenêtre de 90 jours, 50 propositions affichées. Les KPI couvrent toutes les demandes expédiées.']);
